create or replace function public.cineo_restore_metadata(payload jsonb,apply_missing boolean default false) returns jsonb language plpgsql security invoker set search_path='' as $$declare t text;rows jsonb;report jsonb:='[]';n integer;added integer;uid_text text;begin
 if (payload->>'version')::integer<>8 or jsonb_typeof(payload->'tables')<>'object' then raise exception 'Formato de backup inválido';end if;
 foreach t in array array['cineo_shows','cineo_episodes','cineo_profiles','cineo_categories','cineo_collections','cineo_editorial','cineo_preferences','cineo_ratings','cineo_lists','cineo_list_items','cineo_viewers','cineo_viewer_progress','cineo_viewer_saved','cineo_follows','cineo_progress','cineo_saved','cineo_likes','cineo_comments','cineo_comment_likes','cineo_show_info','cineo_episode_notes','cineo_polls','cineo_poll_votes','cineo_library_choices','cineo_bookmarks','cineo_experience','cineo_surveys','cineo_survey_votes','cineo_notices','cineo_feature_flags','cineo_release_news','cineo_tickets','cineo_appeals','cineo_cases','cineo_case_notes','cineo_case_actions','cineo_revisions','cineo_proposals']loop
 rows=coalesce(payload->'tables'->t,'[]');if jsonb_typeof(rows)<>'array' or jsonb_array_length(rows)>5000 then raise exception 'Tabela inválida no backup';end if;
 for uid_text in select distinct v.value#>>'{}' from jsonb_array_elements(rows) as r(rowdata) cross join lateral jsonb_each(r.rowdata) as v(key,value) where v.key in ('user_id','owner_id','author_id','assignee') and v.value<>'null'::jsonb loop if not exists(select 1 from auth.users where id=uid_text::uuid) or exists(select 1 from public.cineo_erasure where user_id=uid_text::uuid) then raise exception 'Uma conta referenciada não existe ou está em exclusão. O backup não restaura contas de autenticação.';end if;end loop;
 execute format('create temporary table %I (like public.%I including constraints) on commit drop','probe_'||t,t);
 execute format('insert into %I select * from jsonb_populate_recordset(null::public.%I,$1)','probe_'||t,t) using rows;get diagnostics n=row_count;added=0;
 if apply_missing and n>0 then execute format('insert into public.%I overriding system value select * from %I on conflict do nothing',t,'probe_'||t);get diagnostics added=row_count;end if;
 report=report||jsonb_build_array(jsonb_build_object('table',t,'checked',n,'inserted',added));end loop;
 return jsonb_build_object('ok',true,'applied',apply_missing,'tables',report,'mode','Somente registros ausentes. Dados existentes não são substituídos.','media_included',false,'auth_included',false);end$$;
revoke all on function public.cineo_backup_snapshot(),public.cineo_restore_metadata(jsonb,boolean) from public,anon,authenticated;
grant execute on function public.cineo_backup_snapshot(),public.cineo_restore_metadata(jsonb,boolean) to service_role;

create or replace function public.cineo_decide_case(actor uuid,cid uuid,decision text,note text) returns void language plpgsql security invoker set search_path='' as $$declare c public.cineo_cases;r text;s public.cineo_shows;e public.cineo_episodes;p public.cineo_proposals;patch jsonb;reportrow public.cineo_reports;begin
 select * into c from public.cineo_cases where id=cid for update;if c.id is null or c.status<>'open' then raise exception 'Caso indisponível';end if;
 if exists(select 1 from public.cineo_admins where user_id=actor) then r:='admin';else select role into r from public.cineo_staff where user_id=actor;if c.assignee is distinct from actor then raise exception 'Caso atribuído a outra pessoa';end if;end if;
 if r is null or (c.kind='ticket' and r not in ('admin','support')) or(c.kind<>'ticket' and r not in ('admin','reviewer')) then raise exception 'Acesso restrito';end if;
 if decision not in ('approved','rejected','resolved','dismissed','restore') or length(note)>2000 or(decision='rejected' and length(trim(note))<3) then raise exception 'Decisão ou motivo inválidos';end if;
 if c.kind='show' then select * into s from public.cineo_shows where id=c.target_id::bigint for update;if s.status<>'pending' or decision not in ('approved','rejected') then raise exception 'Produção não está em análise';end if;if decision='approved' and exists(select 1 from public.cineo_media_jobs j join public.cineo_episodes ep on ep.id=j.episode_id where ep.show_id=s.id and j.status<>'ready') then raise exception 'Vídeos ainda não validados';end if;update public.cineo_shows set status=decision,reason=case when decision='rejected' then note else '' end where id=s.id;if decision='approved' then perform public.cineo_notify(s.id,null);end if;
 elsif c.kind='episode' then select * into e from public.cineo_episodes where id=c.target_id::bigint for update;select * into s from public.cineo_shows where id=e.show_id for update;if e.review_status<>'pending' or s.status<>'approved' or decision not in ('approved','rejected') then raise exception 'Capítulo não está em análise';end if;if decision='approved' and exists(select 1 from public.cineo_media_jobs where episode_id=e.id and status<>'ready') then raise exception 'Arquivo ainda não validado';end if;update public.cineo_episodes set review_status=decision,review_reason=case when decision='rejected' then note else '' end where id=e.id;if decision='approved' then perform public.cineo_notify(s.id,e.id);end if;
 elsif c.kind='proposal' then select * into p from public.cineo_proposals where id=c.target_id::uuid for update;select * into s from public.cineo_shows where id=p.show_id for update;if p.status<>'pending' or s.status<>'approved' or decision not in ('approved','rejected') then raise exception 'Alteração indisponível';end if;patch=p.content->'patch';if decision='approved' then if (p.content->'base'->>'title') is distinct from s.title or(p.content->'base'->>'cover_path') is distinct from s.cover_path then raise exception 'A publicação mudou. Solicite uma proposta atualizada';end if;update public.cineo_shows set title=coalesce(patch->>'title',title),synopsis=coalesce(patch->>'synopsis',synopsis),genre=coalesce(patch->>'genre',genre),rating=coalesce(patch->>'rating',rating),cover_path=coalesce(patch->>'cover_path',cover_path),banner_path=coalesce(patch->>'banner_path',banner_path) where id=s.id;end if;update public.cineo_proposals set status=decision,reason=note where id=p.id;
 elsif c.kind='ticket' then if length(trim(note))<3 then raise exception 'Escreva a resposta';end if;update public.cineo_tickets set reply=note,status='closed' where id=c.target_id::bigint;
 elsif c.kind='appeal' then if length(trim(note))<3 then raise exception 'Explique a reavaliação';end if;update public.cineo_appeals set reply=note,status='answered' where id=c.target_id::bigint;
 elsif c.kind='report' then
 if decision not in ('resolved','restore','dismissed') then raise exception 'Decisão inválida para denúncia';end if;
 select * into reportrow from public.cineo_reports where id=c.target_id::bigint for update;
 if reportrow.id is null then raise exception 'Denúncia não encontrada';end if;
 if decision<>'dismissed' then
 if reportrow.kind='show' then update public.cineo_shows set hidden=(decision='resolved') where id=reportrow.target_id;
 elsif reportrow.kind='episode' then update public.cineo_episodes set hidden=(decision='resolved') where id=reportrow.target_id;
 elsif reportrow.kind='comment' then update public.cineo_comments set hidden=(decision='resolved') where id=reportrow.target_id;else raise exception 'Conteúdo inválido';end if;end if;
 update public.cineo_reports set status=case when decision='dismissed' then 'dismissed' else 'resolved' end where id=reportrow.id;
 else raise exception 'Tipo de caso inválido';end if;
 insert into public.cineo_case_actions(case_id,user_id,action,details) values(c.id,actor,decision,jsonb_build_object('note',note));update public.cineo_cases set status='resolved' where id=c.id;
end$$;


create or replace function public.cineo_ticket_timestamp() returns trigger language plpgsql security invoker set search_path='' as $$begin new.updated_at=now();return new;end$$;
revoke all on function public.cineo_ticket_timestamp() from public,anon,authenticated;
create trigger cineo_ticket_timestamp before update on public.cineo_tickets for each row execute function public.cineo_ticket_timestamp();
